        "weight": 0.3,
        "rubric": {
          "0": "人物坐卧、倒挂或身体方向混乱，无法形成面向画外目标的站立动作",
          "1": "人物基本站立并朝向前方，但支撑姿态松散，装备方向与身体朝向不一致",
          "2": "人物双脚或身体形成稳定支撑，整体朝向画外远处目标，装备方向与视线和躯干一致"
        },
        "acceptable_variants": [
          "采用侧身站姿或半蹲姿态，只要身体支撑稳定且整体朝向远处目标",
          "使用发射瞬间的动态姿势，但重心、视线和装备方向保持一致"
        ]
      }
    ],
    "facet_tags": [
      "character_likeness",
      "tech_machinery",
